CREATE SEQUENCE IF NOT EXISTS TRIALS.SEQ_MATERIA_PERICIAL_ID
START WITH 10;

ALTER SEQUENCE TRIALS.SEQ_MATERIA_PERICIAL_ID
INCREMENT BY 10;

DROP TABLE IF EXISTS TRIALS.TBL_MATERIA_PERICIAL;

CREATE TABLE TRIALS.TBL_MATERIA_PERICIAL (
    PN_ID INT NOT NULL PRIMARY KEY,
    S_NOMBRE VARCHAR(150) NOT NULL
);






